    "Not selected";
  $("next").disabled = !canContinue();

  if (announce) {
    $("status").textContent =
      `Summary updated. ${$("sum-service").textContent}. ` +
      `Price: ${$("sum-price").textContent}. ` +
      `Vet: ${$("sum-vet").textContent}. ` +
      `Time: ${$("sum-time").textContent}.`;
  }
}

function render(focus = true) {
  const titles = [
    "Choose a service", "Choose a vet", "Choose a time",
    "Review & confirm", "Demo appointment confirmed"
  ];
  let body = "";

  if (state.step === 0) {
    body = `<p class="muted">Common visits first. Prices are shown before booking.</p>
      <fieldset><legend>Service and price</legend><div class="options">
      ${Object.entries(services).map(([name, service]) =>
        radio("service", name, state.service === name, name,
          `${service.minutes} min · ${service.price}` +
          (service.restricted ? " · Dr. Mary Major only" : ""))
      ).join("")}
      </div></fieldset>
      <p class="muted">Dental cleaning starts at $280, not a final total.
      An exact quote must be supplied and accepted before booking.</p>`;
  }

  if (state.step === 1) {
    const eligible = Object.keys(vets).filter(vet =>
      qualifies(vet, state.service) && vets[vet].includes(DAY)
    );
    const countText = vet => {
      const count = matching(vet).length;
      return `${count} bookable ${count === 1 ? "time" : "times"} in the supplied Thursday data`;
    };
    body = `<p class="muted">“Any” shows all eligible vets together.
      Picking a time assigns the named vet.</p>
      <fieldset><legend>Vet preference</legend><div class="options">
      ${radio("vet", "any", state.vet === "any", "Any available vet",
        countText("any") +
        (services[state.service].restricted ? " · Dr. Mary Major only" : ""))}
      ${eligible.map(vet => radio("vet", vet, state.vet === vet,
        `Dr. ${vet}`, countText(vet))).join("")}
      </div></fieldset>`;
  }

  if (state.step === 2) {
    const available = matching().sort((a, b) => a.start.localeCompare(b.start));
    body = `<p><strong>Thursday, October 15, 2026</strong><br>
      <span class="muted">Demo date · clinic-local time · 24-hour clock</span></p>`;
    body += available.length ?
      `<fieldset><legend>Available appointment times</legend>
      <div class="options times">
      ${available.map(slot => radio("slot", slot.id, state.slot === slot.id,
        range(slot), `Dr. ${slot.vet}`)).join("")}
      </div></fieldset>` :
      `<div class="notice"><strong>No bookable times in the supplied data.</strong>
      <p>Go back to change your vet or service.
      Other dates are not included in this demo. This does not mean
      the clinic is fully booked.</p></div>`;
    body += `<p class="muted">Hours: 09:00–17:00.
      Closed for lunch 12:00–13:00. The full visit must fit within opening hours.</p>`;
  }

  if (state.step === 3) {
    body = `<p>Check the appointment below before confirming.</p>
      <div class="edits" aria-label="Edit appointment">
        <button type="button" data-edit="0">Edit service</button>
        <button type="button" data-edit="1">Edit vet</button>
        <button type="button" data-edit="2">Edit time</button>
      </div>`;
    if (services[state.service].estimate) {
      body += `<p class="notice">Booking is blocked until the clinic supplies
        an exact total for you to accept. “From $280” is not a final price.</p>`;
    }
  }

  if (state.step === 4) {
    body = `<p>This is a prototype confirmation only.
      No appointment was sent to the clinic.</p>`;
  }

  $("screen").innerHTML =
    `<h2 id="step-title" tabindex="-1">${titles[state.step]}</h2>${body}`;

  document.querySelectorAll(".progress li").forEach((item, index) => {
    item.removeAttribute("aria-current");
    if (index === Math.min(state.step, 3))
      item.setAttribute("aria-current", "step");
  });
