  $("actions").hidden = state.step === 4;
  $("next").textContent = [
    "Continue to vet", "Continue to times", "Review appointment",
    "Confirm demo booking", ""
  ][state.step];
  sync();
  if (focus) $("step-title").focus();
}

$("booking").addEventListener("change", event => {
  const input = event.target;
  if (input.name === "service") {
    state.service = input.value;
    state.vet = "any";
    state.slot = "";
  } else if (input.name === "vet") {
    state.vet = input.value;
    state.slot = "";
  } else if (input.name === "slot") {
    state.slot = input.value;
  }
  // Do not re-render radios: preserve keyboard and screen-reader focus.
  sync(true);
});

$("back").addEventListener("click", () => {
  state.step--;
  render();
});
$("booking").addEventListener("click", event => {
  const edit = event.target.closest("[data-edit]");
  if (!edit) return;
  state.step = Number(edit.dataset.edit);
  render();
});
$("booking").addEventListener("submit", event => {
  event.preventDefault();
  if (!canContinue()) return;
  // Local rule recheck only. Production must atomically revalidate and
  // reserve on the server before displaying a real confirmation.
  state.step++;
  render();
});
render(false);
</script>
</body>
</html>
