    document.querySelectorAll('li[data-plan]').forEach((card) => {
      const plan = PLANS[card.dataset.plan];
      card.querySelector('[data-amount]').textContent =
        fmt(period === 'annual' ? plan.annual : plan.monthly);
      card.querySelector('[data-billed]').textContent = billedText(plan, period);
    });
  }

  toggle.addEventListener('change', () => {
    const period = getPeriod();
    render(period);
    status.textContent = period === 'annual'
      ? 'Showing annual prices, billed yearly.'
      : 'Showing monthly prices, billed monthly.';
  });

  // Browsers can restore radio state on back/forward navigation, so re-sync
  // the prices silently.
  render(getPeriod());
  window.addEventListener('pageshow', () => render(getPeriod()));

  // CTA loading state. aria-disabled (not the disabled attribute) keeps focus on the button.
  document.querySelectorAll('.plan__cta').forEach((btn) => {
    btn.addEventListener('click', async () => {
      if (btn.getAttribute('aria-disabled') === 'true') return;
      const label = btn.querySelector('.plan__cta-label');
      const idleText = label.textContent;
      const plan = PLANS[btn.dataset.plan];

      btn.setAttribute('aria-disabled', 'true');
      label.textContent = 'Starting…';
      status.textContent = `Starting your ${plan.name} plan…`;

