<script>
"use strict";
const $ = id => document.getElementById(id);
const form = $("details");
const fieldIds = ["name", "email", "card", "exp", "cvc", "captcha"];
const labels = {
  name: "Full name", email: "Email address", card: "Card number",
  exp: "Expiry date", cvc: "Security code", captcha: "Verification code"
};
const errors = new Map();
let expiry = Date.now() + 120000;
let expired = false;
let warned = false;
let complete = false;
let ticker;

function expiryIsValid(value) {
  const text = value.trim();
  let month, year;
  const separated = text.match(/^(\d{1,2})\s*\/\s*(\d{2}|\d{4})$/);
  const compact = text.match(/^(\d{2})(\d{2}|\d{4})$/);
  const match = separated || compact;
  if (!match) return false;
  month = Number(match[1]);
  year = Number(match[2]);
  if (match[2].length === 2) year += 2000;
  const now = new Date();
  return month >= 1 && month <= 12 &&
    (year > now.getFullYear() ||
      (year === now.getFullYear() && month >= now.getMonth() + 1));
}

function errorFor(id) {
  const input = $(id);
  const value = input.value.trim();
  if (!value) return `Enter your ${labels[id].toLowerCase()}.`;

  if (id === "email" && input.validity.typeMismatch)
    return "Enter an email address such as alex@example.com.";

  if (id === "card") {
    const digits = value.replace(/[\s-]/g, "");
    // Illustrative syntax check only, not payment authorization.
    if (!/^[\d\s-]+$/.test(value) || !/^\d{12,19}$/.test(digits))
      return "Enter 12–19 digits; spaces and hyphens are allowed.";
  }
  if (id === "exp" && !expiryIsValid(value))
    return "Enter a current or future expiry, such as 12/29 or 1229.";
  if (id === "cvc" && !/^\d{3,4}$/.test(value))
    return "Enter the three- or four-digit security code.";
  if (id === "captcha" && value.toUpperCase() !== "STAGE")
    return "Enter STAGE, or use the fill demo verification code button.";
  return "";
}

function validateField(id) {
  const message = errorFor(id);
  $(id + "-error").textContent = message;
  if (message) {
    errors.set(id, message);
    $(id).setAttribute("aria-invalid", "true");
  } else {
    errors.delete(id);
    $(id).removeAttribute("aria-invalid");
  }
}

function renderErrors(focusSummary = false) {
  $("error-list").replaceChildren();
  for (const id of fieldIds) {
    if (!errors.has(id)) continue;
    const li = document.createElement("li");
    const link = document.createElement("a");
    link.href = "#" + id;
    link.textContent = `${labels[id]}: ${errors.get(id)}`;
    link.addEventListener("click", event => {
      event.preventDefault();
      $(id).focus();
    });
    li.append(link);
    $("error-list").append(li);
  }
  $("error-summary").hidden = errors.size === 0;
  if (focusSummary && errors.size) $("error-summary").focus();
}

fieldIds.forEach(id => {
  $(id).addEventListener("input", () => {
    if (errors.has(id)) {
      validateField(id);
      renderErrors();
    }
  });
});

$("fill-code").addEventListener("click", () => {
  $("captcha").value = "STAGE";
  validateField("captcha");
  renderErrors();
  $("captcha").focus();
});

function updateTimer() {
  if (complete) return;
  const seconds = Math.max(0, Math.ceil((expiry - Date.now()) / 1000));
  const minutes = Math.floor(seconds / 60);
  $("timer").textContent =
    `${minutes} ${minutes === 1 ? "minute" : "minutes"} ` +
    `${String(seconds % 60).padStart(2, "0")} seconds`;

  if (seconds === 0 && !expired) {
    expired = true;
    $("extend").hidden = true;
    $("restart").hidden = false;
    $("review-button").disabled = true;
    $("pay").disabled = true;
    $("hold-status").textContent = "";
    $("hold-alert").textContent =
      "Your demo hold expired. Your details remain on this page. " +
      "Use Restart demo hold to continue. In live checkout, ticket " +
      "availability and price must be checked again.";
    // No navigation and no unexpected focus movement.
  } else if (seconds > 0 && seconds <= 60 && !warned) {
    warned = true;
    $("hold-alert").textContent =
      "One minute or less remains. Use Add 2 minutes above to extend your hold.";
  }
}

function holdIsActive() {
  updateTimer();
  if (!expired) return true;
  $("restart").focus();
  return false;
}

$("extend").addEventListener("click", () => {
  updateTimer();
  if (expired) {
    $("restart").focus();
    return;
  }
  // Demo only. Production must await a successful server extension.
  expiry += 120000;
  warned = false;
  $("hold-alert").textContent = "";
  updateTimer();
  $("hold-status").textContent =
    "Hold extended by two minutes. " + $("timer").textContent + " remain.";
});

$("restart").addEventListener("click", () => {
  // Demo only: no real reservation or availability claim.
  // Production must revalidate stock/price before enabling purchase.
  expiry = Date.now() + 120000;
  expired = false;
  warned = false;
  $("extend").hidden = false;
  $("restart").hidden = true;
  $("review-button").disabled = false;
  $("pay").disabled = false;
  $("hold-alert").textContent = "";
  $("hold-status").textContent =
    "Demo hold restarted for two minutes. No real tickets are reserved.";
  updateTimer();
  $("extend").focus();
});

form.addEventListener("submit", event => {
  event.preventDefault();
  if (!holdIsActive()) return;

  $("email").value = $("email").value.trim();
  fieldIds.forEach(validateField);
  renderErrors(true);
  if (errors.size) return;

  $("review-name").textContent = $("name").value.trim();
  $("review-email").textContent = $("email").value;
  $("review-phone").textContent = $("phone").value.trim() || "Not provided";
  $("review-card").textContent =
    "Card ending " + $("card").value.replace(/[\s-]/g, "").slice(-4);
  $("review-news").textContent =
    $("news").checked ? "Yes — email news and offers" : "No";

  form.hidden = true;
  $("review").hidden = false;
  $("review-heading").focus();
});

$("edit").addEventListener("click", () => {
  $("review").hidden = true;
  form.hidden = false;
  $("email").focus();
});

$("pay").addEventListener("click", () => {
  if (!holdIsActive() || complete) return;

  // Production: use PSP tokenization, server-authoritative totals,
  // an atomic hold check, and an idempotent payment endpoint.
  // Recover accessibly from declines and unknown/network outcomes.
  complete = true;
  clearInterval(ticker);
  ["card", "exp", "cvc"].forEach(id => { $(id).value = ""; });
  $("review-card").textContent = "";
  $("review").hidden = true;
  $("extend").hidden = true;
  $("restart").hidden = true;
